import { expect } from '@skyramp/skyramp';
import type { Page } from '@playwright/test';

export async function submitOwnerForm(page: Page, firstName: string, lastName: string, address: string, city: string, telephone: string) {
    await page.locator("#firstName").fill(firstName);
    await page.locator("#lastName").fill(lastName);
    await page.locator("#address").fill(address);
    await page.locator("#city").fill(city);
    await page.locator("#telephone").fill(telephone);
    // The submit button stays disabled until the form validates, so wait on it
    // rather than on a fixed delay.
    await expect(page.getByRole("button", { name: "Update Owner" })).toBeEnabled();
    const responsePromise = page.waitForResponse("**/petclinic/api/owners/**");
    await page.getByRole("button", { name: "Update Owner" }).click();
    return await responsePromise;
}
